<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/session.php';if(isset($_SESSION['admin_id'])){header('Location: dashboard.php');exit;}$e='';if($_SERVER['REQUEST_METHOD']==='POST'){$u=trim($_POST['username']??'');$p=$_POST['password']??'';$s=$conn->prepare('SELECT id,username,password FROM admins WHERE username=?');$s->bind_param('s',$u);$s->execute();$a=$s->get_result()->fetch_assoc();if($a&&password_verify($p,$a['password'])){$_SESSION['admin_id']=$a['id'];$_SESSION['admin_username']=$a['username'];header('Location: dashboard.php');exit;}$e='Invalid admin credentials.';}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Login</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="container" style="max-width:520px"><div class="card" style="margin-top:60px"><div class="title"><h2>🌿 StressCare Admin</h2><p>Administrator login</p></div><?php if($e):?><div class="alert error"><?=htmlspecialchars($e)?></div><?php endif;?><form method="post"><div class="form-group"><label>Username</label><input name="username" required></div><div class="form-group"><label>Password</label><input type="password" name="password" required></div><button class="btn">Login</button></form><p style="font-size:10px;color:#899891;margin-top:15px">Default: admin / admin123</p></div></main></body></html>
